#!/usr/bin/env python3
"""The brief 20 part B I/O-timing table from the golden reports: results/20_timing_exceptions/io_table.md and .json.
    make_table.py [--check]      (--check: exit 1 if the committed table differs from the goldens)"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[3]
sys.path.insert(0, str(ROOT))
from flow import exceptions_check, gates, io_check  # noqa: E402

OUT = ROOT / "results" / "20_timing_exceptions"
WHAT = {
    "io_i1": "system-synchronous ADC input, -max tCO_max+trace, -min tCO_min+trace",
    "io_i2": "same, -max only",
    "io_i3": "same, -min and -max swapped",
    "io_i3b": "same, -min with the wrong sign",
    "io_i8": "same, 0 ns placeholder on the ADC data",
    "io_i9": "slow ports (button, LED, UART) with 0 ns placeholders and no false path",
    "io_i10": "slow ports with invented delays (-max 2.0 in; -1.5/-2.0 out), as agent runs of part A wrote",
    "io_v6": "ADC on its own oscillator, timed against a virtual clock",
    "io_i4": "system-synchronous DAC output, -max tSU+trace, -min -tH+trace",
    "io_i4b": "same, -min = +tH+trace (wrong sign)",
    "io_v1": "DAC on the oscillator's copy: virtual clock, same numbers as I4",
    "io_v3": "V1 + set_clock_latency -source 0.3 and set_clock_uncertainty 0.1 on the virtual clock",
    "io_v4": "V1 with the virtual clock defined after the delays",
    "io_v5": "V1 with the virtual clock at 12 ns (the interface is 10 ns)",
    "io_i7": "forwarded clock (ODDR, inverted), create_generated_clock -invert on the port, outputs on it",
    "io_i7c": "same generated clock written -edges {2 3 4}",
    "io_i7b": "same, outputs relative to sys_clk instead of the forwarded clock",
    "io_i5": "source-synchronous DDR input, centre-aligned, both edges (-clock_fall -add_delay)",
    "io_i5b": "same, the falling-edge lines without -add_delay",
    "io_i6": "edge-aligned DDR input, direct BUFIO capture",
    "io_i6b": "same with a fixed IDELAYE2 in each data input",
    "io_v2a": "input captured on a 125 MHz MMCM clock, delays relative to the 100 MHz board clock",
    "io_v2": "same, delays relative to a 125 MHz virtual clock",
}


def row(name: str, ifs: list) -> dict:
    g = HERE / "golden" / name
    xdc = HERE / "xdc" / f"{name}.xdc"
    r = io_check.evaluate(g, "route", [xdc], ifs, None, None, dump=g / "io_paths.txt")
    ct = gates.parse_check_timing((g / "check_timing.rpt").read_text())
    msgs = exceptions_check.xdc_messages((g / "vivado.log").read_text())
    ts = gates.parse_timing_summary((g / "timing_summary.rpt").read_text())
    io = io_check.parse_io_dump((g / "io_paths.txt").read_text())
    ports = [p for p in r["interfaces"][0]["ports"]] if r["interfaces"] else []
    p0 = io["ports"].get(ports[0]) if ports else None
    pth = (p0 or {}).get("paths") or {}
    return {"fixture": name, "what": WHAT.get(name, ""),
            "setup_slack_ns": (pth.get("max") or {}).get("slack"), "setup_requirement_ns": (pth.get("max") or {}).get("requirement"),
            "hold_slack_ns": (pth.get("min") or {}).get("slack"), "io_delay_max_ns": (pth.get("max") or {}).get("io_delay"),
            "io_delay_min_ns": (pth.get("min") or {}).get("io_delay"), "uncertainty_ns": (pth.get("max") or {}).get("uncertainty"),
            "iob": (p0 or {}).get("iob"), "wns_ns": ts["wns_ns"], "whs_ns": ts["whs_ns"],
            "check_timing": {k: v for k, v in ct.items() if v and k in gates.UNCONSTRAINED_CHECKS},
            "vivado_messages": sorted({f"{m['severity']} {m['id']}" for m in msgs}),
            "flow_rules": sorted({f["rule"] for f in r["failures"]})}


def build() -> list[dict]:
    fx = yaml.safe_load((HERE / "interfaces.yaml").read_text())["fixtures"]
    return [row(n, ifs) for n, ifs in fx.items() if (HERE / "golden" / n / "io_paths.txt").exists()]


def md(rows: list[dict]) -> str:
    f = lambda x: "-" if x is None else (f"{x:g}" if isinstance(x, float) else str(x))
    out = ["# Brief 20 part B: I/O delays and virtual clocks measured (Vivado 2025.2, xc7a100tcsg324-1, routed)", "",
           "Generated by `flow/tests/fixtures/io_timing/make_table.py` from the goldens. Slack, requirement and delay are",
           "those of the first port of the fixture's interface (ns). \"flow\" = the rules flow/io_check.py raises; Vivado =",
           "messages tied to an XDC line; check_timing = non-zero unconstrained counts.", "",
           "| fixture | case | setup slack (req) | hold slack | delay max/min | unc. | IOB | WNS / WHS | check_timing | Vivado | flow |",
           "|---|---|---|---|---|---|---|---|---|---|---|"]
    for r in rows:
        out.append(f"| {r['fixture'][3:].upper()} | {r['what']} | {f(r['setup_slack_ns'])} ({f(r['setup_requirement_ns'])}) | "
                   f"{f(r['hold_slack_ns'])} | {f(r['io_delay_max_ns'])} / {f(r['io_delay_min_ns'])} | {f(r['uncertainty_ns'])} | "
                   f"{r['iob']} | {f(r['wns_ns'])} / {f(r['whs_ns'])} | "
                   f"{', '.join(f'{k} {v}' for k, v in r['check_timing'].items()) or '-'} | "
                   f"{', '.join(r['vivado_messages']) or '-'} | {', '.join(r['flow_rules']) or 'clean'} |")
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    rows = build()
    text, js = md(rows), json.dumps(rows, indent=2) + "\n"
    if "--check" in sys.argv:
        ok = (OUT / "io_table.md").read_text() == text and (OUT / "io_table.json").read_text() == js
        sys.exit(0 if ok else 1)
    (OUT / "io_table.md").write_text(text)
    (OUT / "io_table.json").write_text(js)
    print(len(rows), "rows")
